package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
	"time"
)

// encodeVideo turns timed JPEG frames into a real-time MP4 (skipped without ffmpeg).
func TestEncodeVideo(t *testing.T) {
	ffmpeg, err := exec.LookPath("ffmpeg")
	if err != nil {
		t.Skip("ffmpeg not installed")
	}
	dir := t.TempDir()
	// Two solid-colour 64x48 frames generated by ffmpeg itself.
	for i, color := range []string{"red", "blue"} {
		out := filepath.Join(dir, "frame-00000"+string(rune('1'+i))+".jpg")
		if msg, err := exec.Command(ffmpeg, "-v", "error", "-f", "lavfi", "-i", "color=c="+color+":s=64x48", "-frames:v", "1", out).CombinedOutput(); err != nil {
			t.Fatalf("make frame: %v %s", err, msg)
		}
	}
	start := time.Now()
	rec := &recorder{dir: dir, started: start, out: filepath.Join(dir, "out.mp4")}
	frames := []recFrame{
		{file: filepath.Join(dir, "frame-000001.jpg"), at: start},
		{file: filepath.Join(dir, "frame-000002.jpg"), at: start.Add(400 * time.Millisecond)},
	}
	path, err := encodeVideo(rec, frames, start.Add(time.Second))
	if err != nil {
		t.Fatal(err)
	}
	if fi, err := os.Stat(path); err != nil || fi.Size() == 0 {
		t.Fatalf("no video written: %v", err)
	}
	probe, err := exec.LookPath("ffprobe")
	if err != nil {
		return
	}
	out, err := exec.Command(probe, "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", path).Output()
	if err != nil {
		t.Fatal(err)
	}
	var secs float64
	if _, err := fmtSscan(string(out), &secs); err != nil || secs < 0.8 || secs > 1.3 {
		t.Errorf("video should last ~1s (real time), got %q", out)
	}
}

func fmtSscan(s string, v *float64) (int, error) { return fmt.Sscan(s, v) }
